#!/usr/bin/env python3
"""Send commands to the QEMU monitor socket (/tmp/qemu-monitor.sock)."""
import socket, sys, time

SOCK = "/tmp/qemu-monitor.sock"

def send(cmds, sock_path=SOCK, delay=0.25):
    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    s.connect(sock_path)
    s.settimeout(0.5)
    out = b""
    time.sleep(0.3)
    try:
        out += s.recv(65536)
    except Exception:
        pass
    for c in cmds:
        s.sendall(c.encode() + b"\n")
        time.sleep(delay)
        try:
            out += s.recv(65536)
        except Exception:
            pass
    s.close()
    return out.decode(errors="replace")

if __name__ == "__main__":
    print(send(sys.argv[1:]))
EOF
