#!/bin/bash
# Start Windows 3.11 for Workgroups under QEMU.
#  - base image kept immutable (-snapshot)
#  - VNC on display :1 (TCP 5901)
#  - QEMU monitor unix socket for programmatic keyboard input (sendkey)
set -e
IMG=/app/isos/win311.img
PIDFILE=/tmp/qemu.pid
MON=/tmp/qemu-monitor.sock

if [ -f "$PIDFILE" ] && kill -0 "$(cat $PIDFILE)" 2>/dev/null; then
    kill "$(cat $PIDFILE)"; sleep 2
fi
rm -f "$MON"

qemu-system-i386 \
    -M pc \
    -cpu 486 \
    -m 16 \
    -hda "$IMG" \
    -snapshot \
    -vga cirrus \
    -netdev user,id=n0 -device ne2k_pci,netdev=n0 \
    -audiodev none,id=a0 -device sb16,audiodev=a0 \
    -k en-us \
    -rtc base=localtime \
    -vnc 0.0.0.0:1 \
    -monitor unix:$MON,server,nowait \
    -pidfile "$PIDFILE" \
    -daemonize
echo "QEMU started (pid $(cat $PIDFILE)); VNC :1 -> 5901; monitor $MON"
EOF
