import sys,re,time; sys.path.insert(0,'/app/bin')
from qmon import send, SOCK
import socket

def dump_text():
    out=send(["xp /500xw 0xb8000"],delay=0.35)
    data=[]
    for line in out.replace('\r','').split('\n'):
        m=re.match(r'^0+[0-9a-f]*:\s+((0x[0-9a-f]{8}\s*)+)',line)
        if m:
            for w in m.group(1).split():
                v=int(w,16); data.append(v&0xff); data.append((v>>16)&0xff)
    return ''.join(chr(c) if 32<=c<127 else ' ' for c in data)

def typ(s):
    m={' ':'spc','\\':'backslash','/':'slash','.':'dot','-':'minus',':':'shift-semicolon','\n':'ret'}
    return ['sendkey '+(m[ch] if ch in m else ch.lower()) for ch in s]

